SELECT ?item ?itemLabel ?itemLabelHi ?lei WHERE {
  ?item wdt:P31/wdt:P279* wd:Q4830453 ;
        wdt:P17 wd:Q668 ;
        wdt:P1278 ?lei .
  OPTIONAL { ?item rdfs:label ?itemLabelHi FILTER(LANG(?itemLabelHi) = "hi") }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 120
